#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package MQTTnet@4.3.1 #:package Disruptor-net@3.4.0 #:package System.Threading.Channels@8.0.0 #:package Microsoft.Extensions.ObjectPool@8.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Buffers; using System.Threading.Channels; using Disruptor; using Disruptor.Dsl; using MQTTnet; using MQTTnet.Client; using MQTTnet.Protocol;  // 1. 定义消息事件 [MemoryPackable] public partial class MqttMessageEvent {     public string Topic { get; set; }     public ReadOnlyMemory<byte> Payload { get; set; }     public MqttQualityOfServiceLevel QoS { get; set; } }  // 2. 实现Disruptor事件处理器 public class MqttMessageEventHandler : IEventHandler<MqttMessageEvent> {     private readonly IMqttClient _mqttClient;     private readonly ObjectPool<Memory<byte>> _memoryPool;      public MqttMessageEventHandler(IMqttClient mqttClient, ObjectPool<Memory<byte>> memoryPool)     {         _mqttClient = mqttClient;         _memoryPool = memoryPool;     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public void OnEvent(MqttMessageEvent data, long sequence, bool endOfBatch)     {         try         {             var message = new MqttApplicationMessageBuilder()                 .WithTopic(data.Topic)                 .WithPayload(data.Payload)                 .WithQualityOfServiceLevel(data.QoS)                 .Build();              _mqttClient.PublishAsync(message).Wait();         }         finally         {             if (!data.Payload.IsEmpty)             {                 _memoryPool.Return(data.Payload);             }         }     } }  // 3. 主服务实现 public class HighPerformanceMqttService : IAsyncDisposable {     private readonly Disruptor<MqttMessageEvent> _disruptor;     private readonly RingBuffer<MqttMessageEvent> _ringBuffer;     private readonly IMqttClient _mqttClient;     private readonly ObjectPool<Memory<byte>> _memoryPool;     private readonly Channel<MqttMessageEvent> _backupChannel;      public HighPerformanceMqttService(IMqttClient mqttClient)     {         _mqttClient = mqttClient;         _memoryPool = new DefaultObjectPool<Memory<byte>>(             new DefaultPooledObjectPolicy<Memory<byte>>(),              1024 * 1024); // 1MB内存池          // 配置Disruptor         _disruptor = new Disruptor<MqttMessageEvent>(             () => new MqttMessageEvent(),             bufferSize: 1024 * 1024, // 1百万消息容量             TaskScheduler.Default,             ProducerType.Multi,             new BlockingWaitStrategy());          _disruptor.HandleEventsWith(new MqttMessageEventHandler(mqttClient, _memoryPool));         _ringBuffer = _disruptor.Start();          // 备用通道(当Disruptor满时使用)         _backupChannel = Channel.CreateBounded<MqttMessageEvent>(new BoundedChannelOptions(10000)         {             FullMode = BoundedChannelFullMode.Wait,             SingleReader = true,             SingleWriter = false         });          _ = ProcessBackupChannelAsync();     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public async ValueTask PublishAsync(string topic, ReadOnlyMemory<byte> payload, MqttQualityOfServiceLevel qos)     {         try         {             var sequence = _ringBuffer.Next();             var messageEvent = _ringBuffer[sequence];             messageEvent.Topic = topic;             messageEvent.Payload = payload;             messageEvent.QoS = qos;             _ringBuffer.Publish(sequence);         }         catch (InsufficientCapacityException)         {             await _backupChannel.Writer.WriteAsync(new MqttMessageEvent             {                 Topic = topic,                 Payload = payload,                 QoS = qos             });         }     }      private async Task ProcessBackupChannelAsync()     {         await foreach (var message in _backupChannel.Reader.ReadAllAsync())         {             var sequence = _ringBuffer.Next();             var messageEvent = _ringBuffer[sequence];             messageEvent.Topic = message.Topic;             messageEvent.Payload = message.Payload;             messageEvent.QoS = message.QoS;             _ringBuffer.Publish(sequence);         }     }      public async ValueTask DisposeAsync()     {         _disruptor.Halt();         _backupChannel.Writer.Complete();         await _mqttClient.DisconnectAsync();     } }  // 4. 启动配置 var builder = WebApplication.CreateBuilder();  // 配置MQTT客户端 builder.Services.AddSingleton<IMqttClient>(sp =>  {     var factory = new MqttFactory();     var client = factory.CreateMqttClient();     var options = new MqttClientOptionsBuilder()         .WithTcpServer("localhost", 1883)         .WithCleanSession()         .Build();     client.ConnectAsync(options).Wait();     return client; });  // 注册高性能MQTT服务 builder.Services.AddSingleton<HighPerformanceMqttService>();  var app = builder.Build(); app.MapGet("/", () => "High Performance MQTT Service Ready"); app.Run();
